using System;
using System.Linq;
using AhnWin52Backup.Core.Paradox;

namespace AhnWin52Backup.Tests.Paradox;

[TestClass]
public sealed class ParadoxBlockCipherTests
{
    [TestMethod]
    public void DecryptDatabaseBlock_UsesTheDataBlockAndChunkNumbers()
    {
        byte[] encrypted = Convert.FromHexString(
            "" +
            "");

        ParadoxBlockCipher.DecryptDatabaseBlock(encrypted, 0x37A75081, 1);

        CollectionAssert.AreEqual(CreateTwoByteSequence(), encrypted);
    }

    [TestMethod]
    public void EncryptDatabaseBlock_ProducesBlocksThatDecryptBackToTheOriginal()
    {
        byte[] original = Enumerable.Range(0, 2048).Select(static value => (byte)(value * 37)).ToArray();
        byte[] encrypted = original.ToArray();

        ParadoxBlockCipher.EncryptDatabaseBlock(encrypted, 0x37A75081, 3);
        Assert.IsFalse(original.SequenceEqual(encrypted));
        ParadoxBlockCipher.DecryptDatabaseBlock(encrypted, 0x37A75081, 3);

        CollectionAssert.AreEqual(original, encrypted);
    }

    [TestMethod]
    public void DecryptMemoBlock_UsesTheMemoCipherParametersForEveryChunk()
    {
        const string encryptedChunk =
            "";
        byte[] encrypted = Convert.FromHexString(encryptedChunk + encryptedChunk);

        ParadoxBlockCipher.DecryptMemoBlock(encrypted, 0x37A75081);

        CollectionAssert.AreEqual(CreateTwoByteSequence(), encrypted);
    }

    private static byte[] CreateTwoByteSequence() =>
        Enumerable.Range(0, 256)
            .Select(static value => (byte)value)
            .Concat(Enumerable.Range(0, 256).Select(static value => (byte)value))
            .ToArray();
}
